INSERT INTO writing_expression (id,scenario_id,expression_type,usage_frequency_level,target_locale,base_locale,display_order,target_expression_text,base_expression_meaning_text,usage_summary,usage_description,representative_question_text,representative_question_translation,representative_sentence_text,representative_sentence_translation,representative_sentence_words,representative_sentence_word_choices,representative_image_url,practice_examples_payload,expression_source,status,difficulty_level,created_at,updated_at) VALUES
(1939,1,'CONVERSATION_SKILL','BASIC','EN','KR',2,'Nice to meet you, too','나도 만나서 반가워','인사를 되받는 Nice to meet you, too','상대가 Nice to meet you라고 먼저 인사했을 때 ''나도 반가워''라고 되받는 표현이에요. 문장 끝에 too를 붙이면 ''나도''라는 뜻이 돼요. 처음 만난 사람과 인사할 때 이 한마디만 알아도 대화를 편하게 시작할 수 있어요.','Hey! I''m Marco, an exchange student from Spain. Nice to meet you!','안녕! 난 Marco고, 스페인에서 온 교환학생이야. 만나서 반가워!','Nice to meet you, too. I''m Jimin.','나도 만나서 반가워. 난 지민이야.',ARRAY['Nice','to','meet','you','too','I''m','Jimin']::varchar[],ARRAY['Jimin','two','your','met','I''m','you','Nice','too','to','meet']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1939/representative/3b91863c-9abf-4fe6-ad52-8299774241c5.webp','[{"sentenceText": "Nice to meet you, too.", "highlightingPart": "Nice to meet you, too", "sentenceTranslation": "나도 만나서 반가워.", "practiceQuestion": "I''m Marco, your new roommate.", "practiceQuestionTranslation": "난 Marco야, 네 새 룸메이트.", "imageUrl": null, "sentenceWords": ["Nice", "to", "meet", "you", "too"], "sentenceWordChoices": ["met", "you", "too", "to", "meet", "two", "your", "Nice"], "sentenceTranslateWords": ["나도", "만나서", "반가워"], "sentenceTranslateWordChoices": ["나도", "반가워", "너도", "미안해", "반가웠어", "만나서"]}, {"sentenceText": "Hi, Ana. Nice to meet you, too.", "highlightingPart": "Nice to meet you, too", "sentenceTranslation": "안녕, Ana. 나도 만나서 반가워.", "practiceQuestion": "This is my friend Ana.", "practiceQuestionTranslation": "여기는 내 친구 Ana야.", "imageUrl": null, "sentenceWords": ["Hi", "Ana", "Nice", "to", "meet", "you", "too"], "sentenceWordChoices": ["two", "Nice", "Hi", "meets", "too", "Hey", "you", "Ana", "meet", "to"], "sentenceTranslateWords": ["안녕", "Ana", "나도", "만나서", "반가워"], "sentenceTranslateWordChoices": ["반가웠어", "만나서", "Ana", "안녕", "잘가", "나도", "너도", "반가워"]}, {"sentenceText": "Nice to meet you, too. I''m in room 302.", "highlightingPart": "Nice to meet you, too", "sentenceTranslation": "나도 만나서 반가워. 난 302호야.", "practiceQuestion": "Nice to meet you! I live next door.", "practiceQuestionTranslation": "만나서 반가워! 난 옆방에 살아.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1939/practice-examples/62a7d80b-0de8-4c1c-84c2-a8f4477a01d0.webp", "sentenceWords": ["Nice", "to", "meet", "you", "too", "I''m", "in", "room", "302"], "sentenceWordChoices": ["in", "I''m", "meet", "you", "302", "two", "at", "Nice", "too", "room", "to", "met"], "sentenceTranslateWords": ["나도", "만나서", "반가워", "난", "302호야"], "sentenceTranslateWordChoices": ["301호야", "반가웠어", "반가워", "302호야", "나도", "난", "만나서", "너도"]}, {"sentenceText": "Nice to meet you, too. Marco told me about you.", "highlightingPart": "Nice to meet you, too", "sentenceTranslation": "나도 만나서 반가워. Marco한테 네 얘기 들었어.", "practiceQuestion": "I''ve heard a lot about you.", "practiceQuestionTranslation": "네 얘기 많이 들었어.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1939/practice-examples/60be49a0-6c53-4ba9-bc47-babf858b5c5e.webp", "sentenceWords": ["Nice", "to", "meet", "you", "too", "Marco", "told", "me", "about", "you"], "sentenceWordChoices": ["you", "tells", "about", "too", "two", "to", "me", "Nice", "your", "meet", "told", "Marco", "you"], "sentenceTranslateWords": ["나도", "만나서", "반가워", "Marco한테", "네", "얘기", "들었어"], "sentenceTranslateWordChoices": ["말했어", "Ana한테", "Marco한테", "반가워", "나도", "들었어", "만나서", "네", "얘기", "너도"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1940,1,'DAILY_ROUTINE','BASIC','EN','KR',1,'I like ~ing','나는 ~하는 걸 좋아해','좋아하는 활동을 말하는 I like ~ing','좋아하는 활동을 말할 때 like 뒤에 동사 원형이 아니라 -ing 형태를 붙여요. I like swim이 아니라 I like swimming처럼요. 취미를 묻는 질문에 가장 쉽고 정확하게 답할 수 있는 기본 표현이에요.','What do you like to do in your free time?','여가 시간에는 뭘 즐겨 해?','I like taking pictures.','나는 사진 찍는 걸 좋아해.',ARRAY['I','like','taking','pictures']::varchar[],ARRAY['like','likes','taking','picture','pictures','I','take']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1940/representative/92e44d69-c359-4fee-8a5d-0863227aaa8e.webp','[{"sentenceText": "I like cooking at home.", "highlightingPart": "I like cooking", "sentenceTranslation": "나는 집에서 요리하는 걸 좋아해.", "practiceQuestion": "What do you do on weekends?", "practiceQuestionTranslation": "넌 주말에 뭐 해?", "imageUrl": null, "sentenceWords": ["I", "like", "cooking", "at", "home"], "sentenceWordChoices": ["like", "I", "cooking", "cook", "at", "home", "likes", "in"], "sentenceTranslateWords": ["나는", "집에서", "요리하는", "걸", "좋아해"], "sentenceTranslateWordChoices": ["걸", "집에서", "나는", "싫어해", "좋아해", "청소하는", "요리하는", "밖에서"]}, {"sentenceText": "Yes, I like swimming.", "highlightingPart": "I like swimming", "sentenceTranslation": "응, 나는 수영하는 걸 좋아해.", "practiceQuestion": "Do you play any sports?", "practiceQuestionTranslation": "너 운동 뭐 해?", "imageUrl": null, "sentenceWords": ["Yes", "I", "like", "swimming"], "sentenceWordChoices": ["swimming", "Yes", "likes", "swim", "I", "swims", "like"], "sentenceTranslateWords": ["응", "나는", "수영하는", "걸", "좋아해"], "sentenceTranslateWordChoices": ["응", "수영하는", "걸", "했어", "싫어해", "달리는", "좋아해", "나는"]}, {"sentenceText": "I like listening to music.", "highlightingPart": "I like listening", "sentenceTranslation": "나는 음악 듣는 걸 좋아해.", "practiceQuestion": "Why do you always have headphones on?", "practiceQuestionTranslation": "너 왜 항상 헤드폰 끼고 있어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1940/practice-examples/e4322b61-193e-4627-bcc5-3d048c6ee9f8.webp", "sentenceWords": ["I", "like", "listening", "to", "music"], "sentenceWordChoices": ["for", "listening", "listen", "like", "likes", "music", "I", "to"], "sentenceTranslateWords": ["나는", "음악", "듣는", "걸", "좋아해"], "sentenceTranslateWordChoices": ["좋아해", "음악", "나는", "영화", "듣는", "싫어해", "걸", "만드는"]}, {"sentenceText": "I like reading before bed.", "highlightingPart": "I like reading", "sentenceTranslation": "나는 자기 전에 책 읽는 걸 좋아해.", "practiceQuestion": "You have so many books.", "practiceQuestionTranslation": "너 책 진짜 많다.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1940/practice-examples/80c58266-3d6e-439e-ba32-51652c386559.webp", "sentenceWords": ["I", "like", "reading", "before", "bed"], "sentenceWordChoices": ["before", "like", "I", "bed", "read", "reading", "after", "likes"], "sentenceTranslateWords": ["나는", "자기", "전에", "책", "읽는", "걸", "좋아해"], "sentenceTranslateWordChoices": ["나는", "읽는", "좋아해", "책", "걸", "싫어해", "후에", "쓰는", "자기", "전에"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1941,1,'TIME_PLANNING','BASIC','EN','KR',3,'in my free time','시간 날 때, 한가할 때','여가 시간을 말하는 in my free time','''시간 날 때'', ''한가할 때''라는 뜻이에요. 여기서 free는 ''무료''가 아니라 ''일정이 비어 있는''이라는 뜻이에요. 취미나 평소 하는 일을 말할 때 문장 앞이나 뒤에 붙이면 자연스러워요.','So what do you usually do when you''re not studying?','그럼 공부 안 할 땐 보통 뭐 해?','I read books in my free time.','나는 시간 날 때 책을 읽어.',ARRAY['I','read','books','in','my','free','time']::varchar[],ARRAY['on','free','time','books','in','reads','my','read','your','I']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1941/representative/c67d035e-bc36-4eb6-ae69-2799193932d2.webp','[{"sentenceText": "I draw in my free time.", "highlightingPart": "in my free time", "sentenceTranslation": "나는 시간 날 때 그림을 그려.", "practiceQuestion": "Do you have any hobbies?", "practiceQuestionTranslation": "너 취미 있어?", "imageUrl": null, "sentenceWords": ["I", "draw", "in", "my", "free", "time"], "sentenceWordChoices": ["draw", "on", "my", "your", "I", "draws", "time", "free", "in"], "sentenceTranslateWords": ["나는", "시간", "날", "때", "그림을", "그려"], "sentenceTranslateWordChoices": ["그림을", "시간", "나는", "그렸어", "바쁠", "때", "그려", "노래를", "날"]}, {"sentenceText": "I watch movies in my free time.", "highlightingPart": "in my free time", "sentenceTranslation": "나는 시간 날 때 영화를 봐.", "practiceQuestion": "How do you relax after class?", "practiceQuestionTranslation": "넌 수업 끝나고 어떻게 쉬어?", "imageUrl": null, "sentenceWords": ["I", "watch", "movies", "in", "my", "free", "time"], "sentenceWordChoices": ["free", "time", "movie", "watches", "watch", "at", "my", "I", "in", "movies"], "sentenceTranslateWords": ["나는", "시간", "날", "때", "영화를", "봐"], "sentenceTranslateWordChoices": ["책을", "봐", "봤어", "때", "날", "바쁠", "나는", "시간", "영화를"]}, {"sentenceText": "Thanks. I practice in my free time.", "highlightingPart": "in my free time", "sentenceTranslation": "고마워. 나는 시간 날 때 연습해.", "practiceQuestion": "You play the guitar really well.", "practiceQuestionTranslation": "너 기타 진짜 잘 친다.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1941/practice-examples/fdc12a41-21d3-44cb-928c-372ae47f42cb.webp", "sentenceWords": ["Thanks", "I", "practice", "in", "my", "free", "time"], "sentenceWordChoices": ["my", "practices", "on", "Thanks", "free", "our", "I", "in", "practice", "time"], "sentenceTranslateWords": ["고마워", "나는", "시간", "날", "때", "연습해"], "sentenceTranslateWordChoices": ["연습해", "때", "바쁠", "연습했어", "날", "시간", "나는", "고마워", "가르쳐"]}, {"sentenceText": "Sure, I walk in the park in my free time.", "highlightingPart": "in my free time", "sentenceTranslation": "그럼, 나는 시간 날 때 공원에서 걸어.", "practiceQuestion": "Do you ever go outside?", "practiceQuestionTranslation": "너 밖에는 좀 나가?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1941/practice-examples/88120c5f-2fb8-401d-b16d-f8f6b6010312.webp", "sentenceWords": ["Sure", "I", "walk", "in", "the", "park", "in", "my", "free", "time"], "sentenceWordChoices": ["the", "park", "walk", "free", "my", "time", "I", "Sure", "in", "your", "walks", "in", "at"], "sentenceTranslateWords": ["그럼", "나는", "시간", "날", "때", "공원에서", "걸어"], "sentenceTranslateWordChoices": ["도서관에서", "걸어", "날", "시간", "공원에서", "그럼", "나는", "걸었어", "때", "뛰어"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1942,1,'RELATIONSHIP_SOCIAL','BASIC','EN','KR',4,'hang out with','~와 놀다, ~와 시간을 보내다','친구랑 노는 hang out with','친구나 가족과 특별한 계획 없이 함께 시간을 보내며 ''논다''는 뜻이에요. play는 아이들이 놀거나 운동·게임을 할 때 쓰고, 어른이 친구랑 논다고 할 땐 hang out을 써요. 과거형은 hanged가 아니라 hung out이에요. 지난 주말에 뭐 했냐는 질문에 제일 자주 나오는 대답이에요.','So, have you done anything fun lately?','그럼, 최근에 재미있는 일 있었어?','I hung out with my friends last weekend.','지난 주말에 친구들이랑 놀았어.',ARRAY['I','hung','out','with','my','friends','last','weekend']::varchar[],ARRAY['hung','last','friends','hanged','with','I','hang','my','weekend','out','friend']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1942/representative/4b6df815-1e37-4763-b71d-3d48a3b4de7f.webp','[{"sentenceText": "I''m going to hang out with Marco.", "highlightingPart": "hang out with", "sentenceTranslation": "Marco랑 놀 거야.", "practiceQuestion": "What are you doing this Friday?", "practiceQuestionTranslation": "이번 금요일에 뭐 해?", "imageUrl": null, "sentenceWords": ["I''m", "going", "to", "hang", "out", "with", "Marco"], "sentenceWordChoices": ["to", "Marco", "hang", "I''m", "hung", "out", "going", "hanging", "with", "play"], "sentenceTranslateWords": ["Marco랑", "놀", "거야"], "sentenceTranslateWordChoices": ["놀", "Ana랑", "거야", "놀았어", "Marco랑", "공부할"]}, {"sentenceText": "I hang out with my roommate a lot.", "highlightingPart": "hang out with", "sentenceTranslation": "룸메이트랑 자주 놀아.", "practiceQuestion": "Who do you usually spend time with?", "practiceQuestionTranslation": "넌 보통 누구랑 시간 보내?", "imageUrl": null, "sentenceWords": ["I", "hang", "out", "with", "my", "roommate", "a", "lot"], "sentenceWordChoices": ["a", "hang", "roommate", "lot", "I", "hung", "with", "hangs", "my", "out", "roommates"], "sentenceTranslateWords": ["룸메이트랑", "자주", "놀아"], "sentenceTranslateWordChoices": ["자주", "친구랑", "놀아", "가끔", "룸메이트랑", "놀았어"]}, {"sentenceText": "Good. I hung out with my cousin.", "highlightingPart": "hung out with", "sentenceTranslation": "좋았어. 사촌이랑 놀았어.", "practiceQuestion": "How was your weekend?", "practiceQuestionTranslation": "주말 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1942/practice-examples/d2fab51b-f871-42fd-94a2-8fd47f4d0049.webp", "sentenceWords": ["Good", "I", "hung", "out", "with", "my", "cousin"], "sentenceWordChoices": ["with", "hung", "Good", "cousin", "I", "hanged", "my", "out", "hang", "cousins"], "sentenceTranslateWords": ["좋았어", "사촌이랑", "놀았어"], "sentenceTranslateWordChoices": ["사촌이랑", "별로였어", "놀았어", "친구랑", "좋았어", "놀아"]}, {"sentenceText": "Sure! I love hanging out with you guys.", "highlightingPart": "hanging out with", "sentenceTranslation": "좋아! 너희랑 노는 거 좋아.", "practiceQuestion": "Do you want to come to the park with us?", "practiceQuestionTranslation": "우리랑 공원 갈래?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1942/practice-examples/756ba3e7-c61e-4106-b68a-d86659dd5a9f.webp", "sentenceWords": ["Sure", "I", "love", "hanging", "out", "with", "you", "guys"], "sentenceWordChoices": ["hanging", "you", "Sure", "hang", "with", "love", "guys", "I", "out", "hung", "loves"], "sentenceTranslateWords": ["좋아", "너희랑", "노는", "거", "좋아"], "sentenceTranslateWordChoices": ["너희랑", "좋아", "싫어", "노는", "걔들이랑", "거", "좋아", "놀았던"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1943,1,'WORK_STUDY','BASIC','EN','KR',2,'major in','~을 전공하다','전공을 밝히는 major in','대학에서 ''~을 전공하다''라는 뜻이에요. 지금 다니고 있다는 뜻으로 I''m majoring in ~처럼 진행형으로 자주 쓰고, 전공 이름 앞에는 관사를 붙이지 않아요. 자기소개할 때 이름 다음으로 가장 자주 나오는 표현이에요.','Can you introduce yourself a little? What do you do?','자기소개를 간단히 해줄래? 어떤 일을 해?','I''m from Korea, and I''m majoring in design.','나는 한국에서 왔고 디자인을 전공하고 있어.',ARRAY['I''m','from','Korea','and','I''m','majoring','in','design']::varchar[],ARRAY['I''m','major','in','design','and','Korea','majoring','I''m','from','on','designer']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1943/representative/f5f157f5-c1b3-4d04-943a-54545c2c8dba.webp','[{"sentenceText": "I''m majoring in computer science.", "highlightingPart": "majoring in", "sentenceTranslation": "나는 컴퓨터공학을 전공하고 있어.", "practiceQuestion": "What do you study here?", "practiceQuestionTranslation": "넌 여기서 뭘 공부해?", "imageUrl": null, "sentenceWords": ["I''m", "majoring", "in", "computer", "science"], "sentenceWordChoices": ["majored", "in", "majoring", "science", "I''m", "major", "computer", "on"], "sentenceTranslateWords": ["나는", "컴퓨터공학을", "전공하고", "있어"], "sentenceTranslateWordChoices": ["전공했어", "경영학을", "가르치고", "나는", "있어", "전공하고", "컴퓨터공학을"]}, {"sentenceText": "Because I major in art history.", "highlightingPart": "major in", "sentenceTranslation": "내가 미술사를 전공하거든.", "practiceQuestion": "Why do you have so many art books?", "practiceQuestionTranslation": "너 왜 미술책이 이렇게 많아?", "imageUrl": null, "sentenceWords": ["Because", "I", "major", "in", "art", "history"], "sentenceWordChoices": ["majoring", "history", "in", "art", "majors", "major", "I", "Because", "on"], "sentenceTranslateWords": ["내가", "미술사를", "전공하거든"], "sentenceTranslateWordChoices": ["수학을", "전공했거든", "내가", "미술사를", "전공하거든", "좋아하거든"]}, {"sentenceText": "No, I''m majoring in music.", "highlightingPart": "majoring in", "sentenceTranslation": "아니, 나는 음악을 전공하고 있어.", "practiceQuestion": "Are we in the same department?", "practiceQuestionTranslation": "우리 같은 과야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1943/practice-examples/3ec6b988-4320-48a5-8c00-ae4caa2fc223.webp", "sentenceWords": ["No", "I''m", "majoring", "in", "music"], "sentenceWordChoices": ["in", "music", "at", "musical", "majoring", "major", "No", "I''m"], "sentenceTranslateWords": ["아니", "나는", "음악을", "전공하고", "있어"], "sentenceTranslateWordChoices": ["전공했어", "가르치고", "있어", "전공하고", "나는", "체육을", "음악을", "아니"]}, {"sentenceText": "I majored in economics for two years.", "highlightingPart": "majored in", "sentenceTranslation": "나는 2년 동안 경제학을 전공했어.", "practiceQuestion": "What was your major back home?", "practiceQuestionTranslation": "본국에서는 전공이 뭐였어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1943/practice-examples/85708298-6581-453e-8ae8-779fdd2bb0a1.webp", "sentenceWords": ["I", "majored", "in", "economics", "for", "two", "years"], "sentenceWordChoices": ["for", "two", "I", "in", "year", "economics", "major", "majored", "on", "years"], "sentenceTranslateWords": ["나는", "2년", "동안", "경제학을", "전공했어"], "sentenceTranslateWordChoices": ["너는", "가르쳤어", "2년", "나는", "동안", "3년", "경제학을", "전공했어"]}]'::jsonb,'SCENARIO','ACTIVE',2,now(),now()),
(1944,1,'OPINION_JUDGMENT','BASIC','EN','KR',1,'What I like about ~ is ~','내가 ~에서 좋아하는 점은 ~야','어떤 점이 좋은지 짚어 말하는 What I like about ~ is ~','무언가의 ''어떤 점''이 좋은지 콕 집어 말할 때 쓰는 틀이에요. What I like about 뒤에 대상, is 뒤에 그 이유를 넣어요. 그냥 I like it이라고 할 때보다 이유가 분명해져서 취미나 취향을 설명할 때 대화가 훨씬 풍성해져요.','You said you like cooking. What do you like about it?','요리 좋아한다고 했지. 어떤 점이 좋아?','What I like about cooking is that I can relax.','요리에서 내가 좋아하는 점은 마음이 편해진다는 거야.',ARRAY['What','I','like','about','cooking','is','that','I','can','relax']::varchar[],ARRAY['I','relaxing','can','is','likes','for','cooking','like','about','relax','What','that','I']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1944/representative/92b132ad-3dd1-454c-af8b-d27991485bf3.webp','[{"sentenceText": "What I like about running is the quiet.", "highlightingPart": "What I like about running is", "sentenceTranslation": "달리기에서 내가 좋아하는 점은 조용하다는 거야.", "practiceQuestion": "Why do you run every morning?", "practiceQuestionTranslation": "넌 왜 매일 아침 달려?", "imageUrl": null, "sentenceWords": ["What", "I", "like", "about", "running", "is", "the", "quiet"], "sentenceWordChoices": ["likes", "What", "for", "about", "quietly", "like", "running", "quiet", "the", "I", "is"], "sentenceTranslateWords": ["달리기에서", "내가", "좋아하는", "점은", "조용하다는", "거야"], "sentenceTranslateWordChoices": ["싫어하는", "달리기에서", "점은", "좋아하는", "시끄럽다는", "조용하다는", "내가", "거야", "수영에서"]}, {"sentenceText": "What I like about movies is the stories.", "highlightingPart": "What I like about movies is", "sentenceTranslation": "영화에서 내가 좋아하는 점은 이야기야.", "practiceQuestion": "You watch a lot of movies.", "practiceQuestionTranslation": "너 영화 진짜 많이 본다.", "imageUrl": null, "sentenceWords": ["What", "I", "like", "about", "movies", "is", "the", "stories"], "sentenceWordChoices": ["stories", "about", "likes", "What", "for", "movies", "like", "story", "the", "is", "I"], "sentenceTranslateWords": ["영화에서", "내가", "좋아하는", "점은", "이야기야"], "sentenceTranslateWordChoices": ["영화에서", "점은", "이야기야", "내가", "싫어하는", "좋아하는", "음악이야", "드라마에서"]}, {"sentenceText": "What I like about the dorm is meeting new people.", "highlightingPart": "What I like about the dorm is", "sentenceTranslation": "기숙사에서 내가 좋아하는 점은 새로운 사람을 만난다는 거야.", "practiceQuestion": "How do you feel about living in a dorm?", "practiceQuestionTranslation": "기숙사 생활 어때?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1944/practice-examples/a664d2c8-7c71-48e8-9399-12ed7deeed00.webp", "sentenceWords": ["What", "I", "like", "about", "the", "dorm", "is", "meeting", "new", "people"], "sentenceWordChoices": ["What", "I", "dorm", "meeting", "people", "the", "is", "likes", "meet", "like", "for", "new", "about"], "sentenceTranslateWords": ["기숙사에서", "내가", "좋아하는", "점은", "새로운", "사람을", "만난다는", "거야"], "sentenceTranslateWordChoices": ["내가", "사람을", "학교에서", "헤어진다는", "점은", "좋아하는", "만난다는", "거야", "싫어하는", "기숙사에서", "새로운"]}, {"sentenceText": "What I like about Seoul is that everything is close.", "highlightingPart": "What I like about Seoul is", "sentenceTranslation": "서울에서 내가 좋아하는 점은 모든 게 가깝다는 거야.", "practiceQuestion": "Is Seoul a good city to live in?", "practiceQuestionTranslation": "서울은 살기 좋은 도시야?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1944/practice-examples/59c040ed-1cf0-400e-b418-3062e18370fe.webp", "sentenceWords": ["What", "I", "like", "about", "Seoul", "is", "that", "everything", "is", "close"], "sentenceWordChoices": ["like", "I", "that", "Seoul", "What", "for", "closely", "is", "likes", "is", "everything", "about", "close"], "sentenceTranslateWords": ["서울에서", "내가", "좋아하는", "점은", "모든", "게", "가깝다는", "거야"], "sentenceTranslateWordChoices": ["서울에서", "부산에서", "멀다는", "내가", "게", "가깝다는", "점은", "모든", "싫어하는", "거야", "좋아하는"]}]'::jsonb,'SCENARIO','ACTIVE',3,now(),now()),
(1945,1,'DAILY_ROUTINE','BASIC','EN','KR',3,'I''ve been ~ing lately','요즘 ~하고 있어','요즘 하고 있는 일을 말하는 I''ve been ~ing lately','얼마 전부터 지금까지 계속하고 있는 일을 말할 때 써요. I''ve been은 I have been의 줄임말이고, 뒤에 -ing를 붙여요. lately는 ''요즘, 최근에''라는 뜻이라 이 표현과 짝처럼 붙어 다녀요. 요즘 뭐 하고 지내냐는 질문에 근황을 자연스럽게 꺼낼 수 있어요.','So, have you done anything fun or memorable lately?','그럼, 최근에 즐겁거나 기억에 남는 일 있어?','I''ve been learning to cook lately.','요즘 요리를 배우고 있어.',ARRAY['I''ve','been','learning','to','cook','lately']::varchar[],ARRAY['to','learning','I''ve','cook','learned','been','lately','cooking','I''m']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1945/representative/9b0d713b-f625-42e0-88a2-bfa431077ccc.webp','[{"sentenceText": "I''ve been studying late lately.", "highlightingPart": "I''ve been studying", "sentenceTranslation": "요즘 늦게까지 공부하고 있어.", "practiceQuestion": "You look tired these days.", "practiceQuestionTranslation": "너 요즘 피곤해 보여.", "imageUrl": null, "sentenceWords": ["I''ve", "been", "studying", "late", "lately"], "sentenceWordChoices": ["late", "I''ve", "studying", "studied", "been", "lately", "I''m", "study"], "sentenceTranslateWords": ["요즘", "늦게까지", "공부하고", "있어"], "sentenceTranslateWordChoices": ["늦게까지", "있어", "공부하고", "일찍", "요즘", "놀고", "있었어"]}, {"sentenceText": "I''ve been working out lately.", "highlightingPart": "I''ve been working out", "sentenceTranslation": "요즘 운동하고 있어.", "practiceQuestion": "You look really fit!", "practiceQuestionTranslation": "너 몸 진짜 좋아졌다!", "imageUrl": null, "sentenceWords": ["I''ve", "been", "working", "out", "lately"], "sentenceWordChoices": ["out", "working", "I''ve", "worked", "lately", "been", "work", "I''m"], "sentenceTranslateWords": ["요즘", "운동하고", "있어"], "sentenceTranslateWordChoices": ["운동하고", "일하고", "있어", "요즘", "있었어", "가끔"]}, {"sentenceText": "I''ve been watching a lot of dramas lately.", "highlightingPart": "I''ve been watching", "sentenceTranslation": "요즘 드라마를 많이 보고 있어.", "practiceQuestion": "How do you know so much about K-dramas?", "practiceQuestionTranslation": "한국 드라마를 어떻게 그렇게 잘 알아?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1945/practice-examples/f6231de4-4dbe-47b1-99d2-42d69b191206.webp", "sentenceWords": ["I''ve", "been", "watching", "a", "lot", "of", "dramas", "lately"], "sentenceWordChoices": ["a", "watching", "dramas", "I''ve", "of", "watched", "lot", "been", "lately", "watch", "drama"], "sentenceTranslateWords": ["요즘", "드라마를", "많이", "보고", "있어"], "sentenceTranslateWordChoices": ["많이", "보고", "조금", "드라마를", "영화를", "있어", "요즘", "봤어"]}, {"sentenceText": "Thanks! I''ve been practicing with Marco lately.", "highlightingPart": "I''ve been practicing", "sentenceTranslation": "고마워! 요즘 Marco랑 연습하고 있어.", "practiceQuestion": "Your Spanish is getting better!", "practiceQuestionTranslation": "너 스페인어 늘었다!", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/1/expressions/1945/practice-examples/cb423c56-d611-4ce7-8c29-08380151bb65.webp", "sentenceWords": ["Thanks", "I''ve", "been", "practicing", "with", "Marco", "lately"], "sentenceWordChoices": ["Marco", "practicing", "Thanks", "with", "practiced", "I''ve", "lately", "been", "practice", "I''m"], "sentenceTranslateWords": ["고마워", "요즘", "Marco랑", "연습하고", "있어"], "sentenceTranslateWordChoices": ["요즘", "Marco랑", "고마워", "Ana랑", "연습하고", "있어", "공부하고", "있었어"]}]'::jsonb,'SCENARIO','ACTIVE',3,now(),now()),
(1946,1,'OPINION_JUDGMENT','BASIC','EN','KR',4,'The best part was ~','제일 좋았던 건 ~였어','제일 좋았던 걸 꼽는 The best part was ~','어떤 경험을 얘기하고 나서 그중 제일 좋았던 점 하나를 꼽을 때 써요. part는 ''부분''이라는 뜻이라 여행·파티·영화 같은 전체 경험 중 한 장면을 콕 집어 말하는 느낌이에요. 뒤에는 명사나 -ing 형태가 오고, 이렇게 한 문장을 덧붙이면 이야기가 훨씬 생생해져요.','Have you done anything memorable lately?','최근에 기억에 남는 일 있었어?','I went camping with friends. The best part was the night sky.','친구들이랑 캠핑 갔어. 제일 좋았던 건 밤하늘이었어.',ARRAY['I','went','camping','with','friends','The','best','part','was','the','night','sky']::varchar[],ARRAY['camping','best','the','went','with','was','The','go','night','I','part','better','friends','sky','is']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1946/representative/2d4be36a-d6b8-4f49-9801-290620349648.webp','[{"sentenceText": "Amazing. The best part was the last song.", "highlightingPart": "The best part was", "sentenceTranslation": "끝내줬어. 제일 좋았던 건 마지막 곡이었어.", "practiceQuestion": "How was the concert last night?", "practiceQuestionTranslation": "어젯밤 콘서트 어땠어?", "imageUrl": null, "sentenceWords": ["Amazing", "The", "best", "part", "was", "the", "last", "song"], "sentenceWordChoices": ["last", "The", "song", "best", "was", "better", "Amazing", "the", "part", "is", "songs"], "sentenceTranslateWords": ["끝내줬어", "제일", "좋았던", "건", "마지막", "곡이었어"], "sentenceTranslateWordChoices": ["제일", "곡이었어", "좋았던", "별로였어", "건", "첫", "마지막", "아쉬웠던", "끝내줬어"]}, {"sentenceText": "Yes! The best part was eating fresh seafood.", "highlightingPart": "The best part was", "sentenceTranslation": "응! 제일 좋았던 건 신선한 해산물을 먹은 거였어.", "practiceQuestion": "Did you enjoy the trip to Busan?", "practiceQuestionTranslation": "부산 여행 재밌었어?", "imageUrl": null, "sentenceWords": ["Yes", "The", "best", "part", "was", "eating", "fresh", "seafood"], "sentenceWordChoices": ["fresh", "The", "eating", "Yes", "best", "part", "eat", "seafood", "was", "better", "were"], "sentenceTranslateWords": ["응", "제일", "좋았던", "건", "신선한", "해산물을", "먹은", "거였어"], "sentenceTran