(1958,6,'POLITE_EXPRESSION','BASIC','EN','KR',4,'Can I bring ~?','내가 ~ 가져가도 돼?','가져가도 되는지 묻는 Can I bring ~?','초대를 받았을 때 ''내가 ~ 가져가도 돼?''라고 묻는 표현이에요. 영어권 모임에서는 음식이나 마실 것을 하나씩 챙겨 가는 게 흔해서 초대에 답할 때 아주 자주 나와요. 사람을 데려가도 되는지 물을 때도 그대로 쓸 수 있어요.','There''s another party next week. Do you want to come?','다음 주에도 파티가 있어. 올래?','Yes! Can I bring some drinks?','좋아! 내가 마실 것 좀 가져가도 돼?',ARRAY['Yes','Can','I','bring','some','drinks']::varchar[],ARRAY['any','some','brought','Yes','drink','I','Can','bring','drinks']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1958/representative/067a3497-9cb6-4efe-90c7-db0b57f67c1e.webp','[{"sentenceText": "Thanks! Can I bring dessert?", "highlightingPart": "Can I bring", "sentenceTranslation": "고마워! 내가 디저트 가져가도 돼?", "practiceQuestion": "Come to dinner at my place on Friday.", "practiceQuestionTranslation": "금요일에 우리 집에 저녁 먹으러 와.", "imageUrl": null, "sentenceWords": ["Thanks", "Can", "I", "bring", "dessert"], "sentenceWordChoices": ["bringing", "Can", "Thanks", "I", "dessert", "desserts", "bring", "brought"], "sentenceTranslateWords": ["고마워", "내가", "디저트", "가져가도", "돼"], "sentenceTranslateWordChoices": ["내가", "돼", "네가", "디저트", "가져왔어", "먹어도", "가져가도", "고마워"]}, {"sentenceText": "Fun! Can I bring my roommate?", "highlightingPart": "Can I bring", "sentenceTranslation": "재밌겠다! 내가 룸메이트 데려가도 돼?", "practiceQuestion": "We''re having a picnic tomorrow.", "practiceQuestionTranslation": "우리 내일 피크닉 해.", "imageUrl": null, "sentenceWords": ["Fun", "Can", "I", "bring", "my", "roommate"], "sentenceWordChoices": ["I", "brought", "roommates", "Can", "my", "roommate", "Fun", "bring", "bringing"], "sentenceTranslateWords": ["재밌겠다", "내가", "룸메이트", "데려가도", "돼"], "sentenceTranslateWordChoices": ["돼", "네가", "룸메이트", "데려가도", "데려왔어", "내가", "혼자", "재밌겠다"]}, {"sentenceText": "Okay. Can I bring rice?", "highlightingPart": "Can I bring", "sentenceTranslation": "알겠어. 내가 밥 가져가도 돼?", "practiceQuestion": "The potluck starts at six.", "practiceQuestionTranslation": "포틀럭 여섯 시에 시작해.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1958/practice-examples/16d26a94-491b-4762-9e4a-8cab969928cd.webp", "sentenceWords": ["Okay", "Can", "I", "bring", "rice"], "sentenceWordChoices": ["Okay", "brought", "I", "Can", "rice", "bringing", "rices", "bring"], "sentenceTranslateWords": ["알겠어", "내가", "밥", "가져가도", "돼"], "sentenceTranslateWordChoices": ["알겠어", "가져왔어", "네가", "밥", "빵", "가져가도", "돼", "내가"]}, {"sentenceText": "Can I bring fruit, then?", "highlightingPart": "Can I bring", "sentenceTranslation": "그럼 내가 과일 가져가도 돼?", "practiceQuestion": "Everyone brings something to share.", "practiceQuestionTranslation": "다들 나눠 먹을 걸 하나씩 가져와.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1958/practice-examples/2af1a53b-ce76-432e-8ad4-4f47a8e661d3.webp", "sentenceWords": ["Can", "I", "bring", "fruit", "then"], "sentenceWordChoices": ["fruits", "then", "I", "bring", "brought", "bringing", "Can", "fruit"], "sentenceTranslateWords": ["그럼", "내가", "과일", "가져가도", "돼"], "sentenceTranslateWordChoices": ["가져가도", "내가", "돼", "케이크", "가져왔어", "네가", "그럼", "과일"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1959,6,'EMOTION_EMPATHY','BASIC','EN','KR',1,'have a good time','즐겁게 보내다, 재미있게 놀다','즐거운 시간을 보낸다는 have a good time','''즐거운 시간을 보내다''라는 뜻이에요. 지금 즐기고 있으면 I''m having a good time, 지나간 일이면 I had a good time처럼 시제만 바꿔 쓰면 돼요. 더 강조하고 싶으면 good 자리에 great을 넣어요.','How are you enjoying the party?','파티는 재미있어?','I''m having a good time so far.','지금까지는 재미있게 놀고 있어.',ARRAY['I''m','having','a','good','time','so','far']::varchar[],ARRAY['good','have','time','so','times','far','a','I''m','having','near']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1959/representative/75e693bb-87b5-47d6-8849-4f823484ca60.webp','[{"sentenceText": "Yes, we had a good time.", "highlightingPart": "had a good time", "sentenceTranslation": "응, 우리 재미있게 놀았어.", "practiceQuestion": "Was the trip fun?", "practiceQuestionTranslation": "여행 재미있었어?", "imageUrl": null, "sentenceWords": ["Yes", "we", "had", "a", "good", "time"], "sentenceWordChoices": ["a", "Yes", "they", "good", "had", "have", "we", "time", "times"], "sentenceTranslateWords": ["응", "우리", "재미있게", "놀았어"], "sentenceTranslateWordChoices": ["놀았어", "지루했어", "우리", "재미있게", "놀거야", "너희", "응"]}, {"sentenceText": "I''m having a good time here.", "highlightingPart": "having a good time", "sentenceTranslation": "나 여기서 재미있게 놀고 있어.", "practiceQuestion": "You look happy tonight.", "practiceQuestionTranslation": "너 오늘 밤 즐거워 보인다.", "imageUrl": null, "sentenceWords": ["I''m", "having", "a", "good", "time", "here"], "sentenceWordChoices": ["good", "times", "have", "there", "a", "here", "having", "I''m", "time"], "sentenceTranslateWords": ["나", "여기서", "재미있게", "놀고", "있어"], "sentenceTranslateWordChoices": ["나", "있어", "지루해하고", "놀고", "재미있게", "놀았어", "저기서", "여기서"]}, {"sentenceText": "No, I''m having a good time.", "highlightingPart": "having a good time", "sentenceTranslation": "아니, 나 재미있게 놀고 있어.", "practiceQuestion": "Do you want to leave early?", "practiceQuestionTranslation": "일찍 갈래?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1959/practice-examples/348779a9-3717-42c4-802c-a72a40688c41.webp", "sentenceWords": ["No", "I''m", "having", "a", "good", "time"], "sentenceWordChoices": ["having", "had", "I''m", "No", "a", "good", "times", "have", "time"], "sentenceTranslateWords": ["아니", "나", "재미있게", "놀고", "있어"], "sentenceTranslateWordChoices": ["응", "아니", "재미있게", "나", "있어", "놀고", "놀았어", "지루해하고"]}, {"sentenceText": "Great. Everyone had a good time.", "highlightingPart": "had a good time", "sentenceTranslation": "좋았어. 다들 재미있게 놀았어.", "practiceQuestion": "How was last night?", "practiceQuestionTranslation": "어젯밤 어땠어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1959/practice-examples/e6ded8de-e4ba-4b18-be09-22569a771d26.webp", "sentenceWords": ["Great", "Everyone", "had", "a", "good", "time"], "sentenceWordChoices": ["times", "Nobody", "time", "had", "have", "Everyone", "Great", "good", "a"], "sentenceTranslateWords": ["좋았어", "다들", "재미있게", "놀았어"], "sentenceTranslateWordChoices": ["아무도", "좋았어", "지루했어", "다들", "재미있게", "놀거야", "놀았어"]}]'::jsonb,'SCENARIO','ACTIVE',2,now(),now()),
(1960,6,'OPINION_JUDGMENT','BASIC','EN','KR',2,'be a big fan of ~','~을 정말 좋아하다, ~의 팬이다','아주 좋아한다고 밝히는 be a big fan of ~','''~을 아주 좋아한다''는 뜻이에요. 연예인뿐 아니라 음식, 음악, 활동에도 다 쓸 수 있어요. 앞에 not을 붙여 I''m not a big fan of ~라고 하면 ''별로 안 좋아해''라고 부드럽게 거절하는 뜻이 되니까 함께 익혀두면 좋아요.','What kind of music or food do you like at parties?','파티에서 어떤 음악이나 음식을 좋아해?','I''m a big fan of Latin music.','나는 라틴 음악을 정말 좋아해.',ARRAY['I''m','a','big','fan','of','Latin','music']::varchar[],ARRAY['music','I''m','of','fan','fans','the','for','Latin','big','a']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1960/representative/a7ae94eb-834b-433a-9d87-2b8b7f2881d5.webp','[{"sentenceText": "Yes, I''m a big fan of spicy food.", "highlightingPart": "a big fan of", "sentenceTranslation": "응, 나는 매운 음식을 정말 좋아해.", "practiceQuestion": "Do you want to try the spicy wings?", "practiceQuestionTranslation": "매운 윙 먹어볼래?", "imageUrl": null, "sentenceWords": ["Yes", "I''m", "a", "big", "fan", "of", "spicy", "food"], "sentenceWordChoices": ["I''m", "fan", "food", "Yes", "of", "big", "spicy", "a", "for", "foods", "fans"], "sentenceTranslateWords": ["응", "나는", "매운", "음식을", "정말", "좋아해"], "sentenceTranslateWordChoices": ["단", "싫어해", "나는", "너는", "매운", "음식을", "응", "정말", "좋아해"]}, {"sentenceText": "Of course. I''m a big fan of them.", "highlightingPart": "a big fan of", "sentenceTranslation": "당연하지. 나 그 밴드 완전 좋아해.", "practiceQuestion": "Have you heard this band before?", "practiceQuestionTranslation": "이 밴드 전에 들어본 적 있어?", "imageUrl": null, "sentenceWords": ["Of", "course", "I''m", "a", "big", "fan", "of", "them"], "sentenceWordChoices": ["fan", "a", "Of", "course", "of", "they", "for", "big", "I''m", "them", "fans"], "sentenceTranslateWords": ["당연하지", "나", "그", "밴드", "완전", "좋아해"], "sentenceTranslateWordChoices": ["당연하지", "별로", "완전", "좋아해", "싫어해", "밴드", "가수", "그", "나"]}, {"sentenceText": "My roommate is a big fan of their coffee.", "highlightingPart": "a big fan of", "sentenceTranslation": "내 룸메이트가 여기 커피를 정말 좋아하거든.", "practiceQuestion": "Why did you pick this cafe?", "practiceQuestionTranslation": "너 왜 이 카페 골랐어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1960/practice-examples/264fabd4-1343-4b54-abc9-90bd74bc12bd.webp", "sentenceWords": ["My", "roommate", "is", "a", "big", "fan", "of", "their", "coffee"], "sentenceWordChoices": ["fan", "fans", "big", "roommate", "is", "for", "their", "coffee", "a", "My", "of", "are"], "sentenceTranslateWords": ["내", "룸메이트가", "여기", "커피를", "정말", "좋아하거든"], "sentenceTranslateWordChoices": ["정말", "좋아하거든", "케이크를", "여기", "커피를", "룸메이트가", "싫어하거든", "내", "내가"]}, {"sentenceText": "I''m a big fan of old movies.", "highlightingPart": "a big fan of", "sentenceTranslation": "나는 옛날 영화를 정말 좋아해.", "practiceQuestion": "Do you watch a lot of movies?", "practiceQuestionTranslation": "너 영화 많이 봐?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1960/practice-examples/f80e91c6-cfe5-4fe4-8845-a49cd0ece275.webp", "sentenceWords": ["I''m", "a", "big", "fan", "of", "old", "movies"], "sentenceWordChoices": ["fans", "of", "fan", "old", "movies", "movie", "a", "big", "I''m", "for"], "sentenceTranslateWords": ["나는", "옛날", "영화를", "정말", "좋아해"], "sentenceTranslateWordChoices": ["싫어해", "옛날", "영화를", "너는", "정말", "최신", "좋아해", "나는"]}]'::jsonb,'SCENARIO','ACTIVE',3,now(),now()),
(1961,6,'GRAMMAR_FUNCTION_WORD','BASIC','EN','KR',3,'especially','특히, 그중에서도','범위 안에서 하나를 콕 집는 especially','''특히'', ''그중에서도''라는 뜻의 부사예요. 큰 범위를 먼저 말한 뒤 쉼표를 찍고 especially로 그중 하나를 콕 집어 덧붙이면 좋아하는 걸 훨씬 구체적으로 전할 수 있어요. 철자가 비슷한 special(특별한)과 품사가 다르니 헷갈리지 마세요.','What kind of music or food do you like at parties?','파티에서 어떤 음악이나 음식을 좋아해?','I like Korean food, especially spicy dishes.','나는 한국 음식을 좋아해, 특히 매운 거.',ARRAY['I','like','Korean','food','especially','spicy','dishes']::varchar[],ARRAY['food','special','like','I','Korean','likes','dish','especially','dishes','spicy']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1961/representative/6891a293-79ec-482c-9b70-2359bcdaf579.webp','[{"sentenceText": "I listen to pop, especially older songs.", "highlightingPart": "especially", "sentenceTranslation": "나는 팝을 들어, 특히 옛날 노래.", "practiceQuestion": "Do you listen to a lot of music?", "practiceQuestionTranslation": "너 음악 많이 들어?", "imageUrl": null, "sentenceWords": ["I", "listen", "to", "pop", "especially", "older", "songs"], "sentenceWordChoices": ["listens", "songs", "older", "special", "to", "especially", "listen", "song", "pop", "I"], "sentenceTranslateWords": ["나는", "팝을", "들어", "특히", "옛날", "노래"], "sentenceTranslateWordChoices": ["들었어", "재즈를", "최신", "옛날", "들어", "나는", "특히", "노래", "팝을"]}, {"sentenceText": "It was great, especially the cake.", "highlightingPart": "especially", "sentenceTranslation": "좋았어, 특히 케이크가.", "practiceQuestion": "How was the party food?", "practiceQuestionTranslation": "파티 음식 어땠어?", "imageUrl": null, "sentenceWords": ["It", "was", "great", "especially", "the", "cake"], "sentenceWordChoices": ["great", "the", "It", "cakes", "cake", "was", "especially", "is", "special"], "sentenceTranslateWords": ["좋았어", "특히", "케이크가"], "sentenceTranslateWordChoices": ["특히", "피자가", "케이크가", "별로였어", "좋겠어", "좋았어"]}, {"sentenceText": "The drinks are good, especially the tea.", "highlightingPart": "especially", "sentenceTranslation": "음료가 좋아, 특히 차가.", "practiceQuestion": "Why do you go to that cafe so often?", "practiceQuestionTranslation": "너 왜 그 카페 자주 가?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1961/practice-examples/18d31f3c-25bc-4666-9f9e-59b45c4bac2a.webp", "sentenceWords": ["The", "drinks", "are", "good", "especially", "the", "tea"], "sentenceWordChoices": ["drink", "especially", "The", "are", "the", "special", "is", "good", "drinks", "tea"], "sentenceTranslateWords": ["음료가", "좋아", "특히", "차가"], "sentenceTranslateWordChoices": ["특히", "별로야", "좋아", "커피가", "음료가", "좋았어", "차가"]}, {"sentenceText": "I do, especially baking.", "highlightingPart": "especially", "sentenceTranslation": "응, 특히 베이킹.", "practiceQuestion": "Do you enjoy cooking?", "practiceQuestionTranslation": "너 요리하는 거 좋아해?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1961/practice-examples/6218533c-550b-4cf1-8ead-a714dec7f3ab.webp", "sentenceWords": ["I", "do", "especially", "baking"], "sentenceWordChoices": ["baking", "special", "does", "do", "especially", "bake", "I"], "sentenceTranslateWords": ["응", "특히", "베이킹"], "sentenceTranslateWordChoices": ["아니", "응", "베이킹", "특히", "가끔", "설거지"]}]'::jsonb,'SCENARIO','ACTIVE',2,now(),now()),
(1962,6,'TIME_PLANNING','BASIC','EN','KR',4,'What time does ~ start?','~은 몇 시에 시작해?','시작 시각을 물어보는 What time does ~ start?','행사나 모임이 ''몇 시에 시작하는지'' 묻는 표현이에요. 의문문이라 does 뒤에는 -s가 붙지 않은 원형 start를 써요. 초대를 수락한 뒤 이렇게 되물으면 갈 마음이 있다는 게 자연스럽게 전해져요.','My friend has a party next week. Would you like to join us?','내 친구가 다음 주에 파티를 해. 우리랑 같이 갈래?','That sounds fun. What time does it start?','재밌겠다. 몇 시에 시작해?',ARRAY['That','sounds','fun','What','time','does','it','start']::varchar[],ARRAY['start','does','sounds','starts','fun','it','do','That','What','sound','time']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1962/representative/b9571468-45c2-4b93-a86f-5110fd606b76.webp','[{"sentenceText": "What time does the movie start?", "highlightingPart": "What time does", "sentenceTranslation": "영화는 몇 시에 시작해?", "practiceQuestion": "The movie is at the student center.", "practiceQuestionTranslation": "영화는 학생회관에서 해.", "imageUrl": null, "sentenceWords": ["What", "time", "does", "the", "movie", "start"], "sentenceWordChoices": ["do", "the", "start", "starts", "does", "movie", "time", "What", "Where"], "sentenceTranslateWords": ["영화는", "몇", "시에", "시작해"], "sentenceTranslateWordChoices": ["어디서", "끝나", "시에", "몇", "시작했어", "영화는", "시작해"]}, {"sentenceText": "Nice. What time does it start?", "highlightingPart": "What time does", "sentenceTranslation": "좋다. 몇 시에 시작해?", "practiceQuestion": "I signed us up for the cooking class.", "practiceQuestionTranslation": "내가 우리 요리 수업 신청했어.", "imageUrl": null, "sentenceWords": ["Nice", "What", "time", "does", "it", "start"], "sentenceWordChoices": ["What", "do", "starts", "Who", "it", "time", "Nice", "does", "start"], "sentenceTranslateWords": ["좋다", "몇", "시에", "시작해"], "sentenceTranslateWordChoices": ["시에", "시작했어", "몇", "끝나", "좋다", "어디서", "시작해"]}, {"sentenceText": "I won''t. What time does dinner start?", "highlightingPart": "What time does", "sentenceTranslation": "안 늦어. 저녁은 몇 시에 시작해?", "practiceQuestion": "Don''t be late for the potluck.", "practiceQuestionTranslation": "포틀럭에 늦지 마.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1962/practice-examples/4bc1c703-9276-4729-94df-7931d993424e.webp", "sentenceWords": ["I", "won''t", "What", "time", "does", "dinner", "start"], "sentenceWordChoices": ["dinner", "does", "starts", "do", "won''t", "I", "Where", "time", "start", "What"], "sentenceTranslateWords": ["안", "늦어", "저녁은", "몇", "시에", "시작해"], "sentenceTranslateWordChoices": ["끝나", "늦어", "안", "어디서", "시에", "저녁은", "몇", "시작해", "점심은"]}, {"sentenceText": "What time does the show start?", "highlightingPart": "What time does", "sentenceTranslation": "공연은 몇 시에 시작해?", "practiceQuestion": "The concert is on Saturday night.", "practiceQuestionTranslation": "공연은 토요일 밤이야.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/6/expressions/1962/practice-examples/9323ab24-6f69-4ee3-aaba-e1b0449aa1b1.webp", "sentenceWords": ["What", "time", "does", "the", "show", "start"], "sentenceWordChoices": ["show", "the", "starts", "do", "time", "does", "Who", "start", "What"], "sentenceTranslateWords": ["공연은", "몇", "시에", "시작해"], "sentenceTranslateWordChoices": ["시에", "공연은", "어디서", "시작해", "끝나", "몇", "시작했어"]}]'::jsonb,'SCENARIO','ACTIVE',2,now(),now()),
(1963,21,'DAILY_ROUTINE','BASIC','EN','KR',1,'I lost my ~','제 ~을 잃어버렸어요','분실을 알리는 I lost my ~','''~을 잃어버렸어요''라고 말할 때 쓰는 표현이에요. lose의 과거형 lost를 쓰고 뒤에 잃어버린 물건을 넣어요. 도움을 요청할 때 가장 먼저 꺼내는 문장이라 통째로 외워두면 좋아요.','How can I help you?','무엇을 도와드릴까요?','I lost my room key.','제 방 키를 잃어버렸어요.',ARRAY['I','lost','my','room','key']::varchar[],ARRAY['keys','room','I','lose','my','your','lost','key']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1963/representative/cf07d07e-67f6-49a9-b8bc-073a856a3ba1.webp','[{"sentenceText": "I lost my student ID.", "highlightingPart": "I lost my", "sentenceTranslation": "학생증을 잃어버렸어요.", "practiceQuestion": "What''s the problem?", "practiceQuestionTranslation": "무슨 일이세요?", "imageUrl": null, "sentenceWords": ["I", "lost", "my", "student", "ID"], "sentenceWordChoices": ["student", "lose", "your", "my", "students", "I", "lost", "ID"], "sentenceTranslateWords": ["학생증을", "잃어버렸어요"], "sentenceTranslateWordChoices": ["맡겼어요", "여권을", "잃어버렸어요", "학생증을", "찾았어요"]}, {"sentenceText": "Yes, but I lost my wallet.", "highlightingPart": "I lost my", "sentenceTranslation": "네, 그런데 지갑을 잃어버렸어요.", "practiceQuestion": "Did you check your bag?", "practiceQuestionTranslation": "가방은 확인해 보셨어요?", "imageUrl": null, "sentenceWords": ["Yes", "but", "I", "lost", "my", "wallet"], "sentenceWordChoices": ["wallet", "Yes", "but", "my", "lose", "I", "your", "wallets", "lost"], "sentenceTranslateWords": ["네", "그런데", "지갑을", "잃어버렸어요"], "sentenceTranslateWordChoices": ["지갑을", "아니요", "가방을", "찾았어요", "네", "잃어버렸어요", "그런데"]}, {"sentenceText": "I lost my key this morning.", "highlightingPart": "I lost my", "sentenceTranslation": "오늘 아침에 키를 잃어버렸어요.", "practiceQuestion": "Why can''t you get in?", "practiceQuestionTranslation": "왜 못 들어가세요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1963/practice-examples/7232baaf-e4b0-420f-8672-8ef6e4075fe1.webp", "sentenceWords": ["I", "lost", "my", "key", "this", "morning"], "sentenceWordChoices": ["morning", "your", "evening", "this", "I", "lose", "my", "key", "lost"], "sentenceTranslateWords": ["오늘", "아침에", "키를", "잃어버렸어요"], "sentenceTranslateWordChoices": ["찾았어요", "오늘", "저녁에", "아침에", "잃어버렸어요", "어제", "키를"]}, {"sentenceText": "No, I lost my phone, too.", "highlightingPart": "I lost my", "sentenceTranslation": "아니요, 휴대폰도 잃어버렸어요.", "practiceQuestion": "Do you have your phone?", "practiceQuestionTranslation": "휴대폰은 가지고 계세요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1963/practice-examples/79262679-d093-4389-b48c-4b0d59fc13e1.webp", "sentenceWords": ["No", "I", "lost", "my", "phone", "too"], "sentenceWordChoices": ["lost", "lose", "too", "two", "phone", "No", "your", "my", "I"], "sentenceTranslateWords": ["아니요", "휴대폰도", "잃어버렸어요"], "sentenceTranslateWordChoices": ["네", "아니요", "잃어버렸어요", "찾았어요", "휴대폰도", "지갑도"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1964,21,'POLITE_EXPRESSION','BASIC','EN','KR',2,'Can you ~?','~해 주실 수 있어요?','도움을 부탁하는 Can you ~?','''~해 주실 수 있어요?''라고 부탁할 때 쓰는 가장 기본 표현이에요. Can you 뒤에는 동사 원형이 와요. 내가 해도 되는지 물을 때는 주어만 바꿔 Can I ~?라고 하면 돼요.','I can give you a spare key or open the door for you. Which do you want?','여분의 키를 드리거나 문을 열어드릴 수 있어요. 어느 쪽이 좋으세요?','Can you open the door for me?','문을 열어 주실 수 있어요?',ARRAY['Can','you','open','the','door','for','me']::varchar[],ARRAY['I','me','door','the','for','open','you','to','Can','opens']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1964/representative/8188fc80-9d9f-48f1-adbe-ba9ed21d2689.webp','[{"sentenceText": "Can you check it, please?", "highlightingPart": "Can you", "sentenceTranslation": "확인해 주실 수 있어요?", "practiceQuestion": "The elevator is not working.", "practiceQuestionTranslation": "엘리베이터가 작동을 안 해요.", "imageUrl": null, "sentenceWords": ["Can", "you", "check", "it", "please"], "sentenceWordChoices": ["please", "it", "you", "Can", "check", "checks", "them", "I"], "sentenceTranslateWords": ["확인해", "주실", "수", "있어요"], "sentenceTranslateWordChoices": ["수", "있어요", "확인해", "고쳐", "주실", "있었어요", "제가"]}, {"sentenceText": "Can you call me later?", "highlightingPart": "Can you", "sentenceTranslation": "나중에 전화해 주실 수 있어요?", "practiceQuestion": "I''ll write down your room number.", "practiceQuestionTranslation": "방 번호를 적어둘게요.", "imageUrl": null, "sentenceWords": ["Can", "you", "call", "me", "later"], "sentenceWordChoices": ["I", "Can", "calls", "earlier", "me", "later", "you", "call"], "sentenceTranslateWords": ["나중에", "전화해", "주실", "수", "있어요"], "sentenceTranslateWordChoices": ["수", "전화해", "문자해", "나중에", "있어요", "지금", "있었어요", "주실"]}, {"sentenceText": "Can you help me today?", "highlightingPart": "Can you", "sentenceTranslation": "오늘 도와주실 수 있어요?", "practiceQuestion": "The new key is not ready yet.", "practiceQuestionTranslation": "새 키가 아직 준비가 안 됐어요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1964/practice-examples/868408e5-017e-4748-80a0-e8951174abe3.webp", "sentenceWords": ["Can", "you", "help", "me", "today"], "sentenceWordChoices": ["today", "helps", "tomorrow", "I", "help", "me", "you", "Can"], "sentenceTranslateWords": ["오늘", "도와주실", "수", "있어요"], "sentenceTranslateWordChoices": ["기다려", "내일", "있어요", "있었어요", "도와주실", "오늘", "수"]}, {"sentenceText": "Sure. Can you wait a minute?", "highlightingPart": "Can you", "sentenceTranslation": "네. 잠깐 기다려 주실 수 있어요?", "practiceQuestion": "I need your name and room number.", "practiceQuestionTranslation": "성함과 방 번호가 필요해요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1964/practice-examples/05612e61-0c04-4424-962f-7e9149bda2fd.webp", "sentenceWords": ["Sure", "Can", "you", "wait", "a", "minute"], "sentenceWordChoices": ["minute", "minutes", "Sure", "Can", "a", "I", "waits", "wait", "you"], "sentenceTranslateWords": ["네", "잠깐", "기다려", "주실", "수", "있어요"], "sentenceTranslateWordChoices": ["있었어요", "잠깐", "기다려", "주실", "오래", "네", "아니요", "수", "있어요"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1965,21,'CONVERSATION_SKILL','BASIC','EN','KR',3,'That''s okay','괜찮아요','괜찮다고 답하는 That''s okay','상대의 제안이나 상황에 ''괜찮아요''라고 답할 때 쓰는 표현이에요. That''s는 That is의 줄임말이에요. 사과를 받았을 때도 ''괜찮아요, 신경 쓰지 마세요''라는 뜻으로 그대로 쓸 수 있어요.','Your new key can be ready tomorrow. Is morning okay?','새 키는 내일 준비돼요. 오전에 괜찮으세요?','Tomorrow morning? That''s okay.','내일 오전이요? 괜찮아요.',ARRAY['Tomorrow','morning','That''s','okay']::varchar[],ARRAY['morning','That','okay','Tomorrow','Today','evening','That''s']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1965/representative/7a3dc1d6-c9b7-4fb2-8c3c-3cdf14c6abad.webp','[{"sentenceText": "That''s okay. I''ll wait here.", "highlightingPart": "That''s okay", "sentenceTranslation": "괜찮아요. 여기서 기다릴게요.", "practiceQuestion": "The staff will come in ten minutes.", "practiceQuestionTranslation": "직원이 10분 뒤에 갈 거예요.", "imageUrl": null, "sentenceWords": ["That''s", "okay", "I''ll", "wait", "here"], "sentenceWordChoices": ["here", "waits", "okay", "That''s", "I''ll", "there", "wait", "That"], "sentenceTranslateWords": ["괜찮아요", "여기서", "기다릴게요"], "sentenceTranslateWordChoices": ["기다릴게요", "기다렸어요", "괜찮아요", "여기서", "안돼요", "저기서"]}, {"sentenceText": "That''s okay. I can come tomorrow.", "highlightingPart": "That''s okay", "sentenceTranslation": "괜찮아요. 내일 올 수 있어요.", "practiceQuestion": "Sorry, the office closes at six.", "practiceQuestionTranslation": "죄송해요, 사무실은 여섯 시에 닫아요.", "imageUrl": null, "sentenceWords": ["That''s", "okay", "I", "can", "come", "tomorrow"], "sentenceWordChoices": ["comes", "I", "That", "come", "That''s", "today", "can", "okay", "tomorrow"], "sentenceTranslateWords": ["괜찮아요", "내일", "올", "수", "있어요"], "sentenceTranslateWordChoices": ["올", "있어요", "괜찮아요", "수", "오늘", "안돼요", "없어요", "내일"]}, {"sentenceText": "That''s okay. How much is it?", "highlightingPart": "That''s okay", "sentenceTranslation": "괜찮아요. 얼마예요?", "practiceQuestion": "There is a small fee for the new key.", "practiceQuestionTranslation": "새 키는 소액의 수수료가 있어요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1965/practice-examples/fc1ca299-bd28-49f7-b639-bc0cfa1e4b1a.webp", "sentenceWords": ["That''s", "okay", "How", "much", "is", "it"], "sentenceWordChoices": ["much", "it", "are", "That", "is", "okay", "How", "many", "That''s"], "sentenceTranslateWords": ["괜찮아요", "얼마예요"], "sentenceTranslateWordChoices": ["안돼요", "언제예요", "얼마예요", "괜찮아요", "어디예요"]}, {"sentenceText": "That''s okay. No hurry.", "highlightingPart": "That''s okay", "sentenceTranslation": "괜찮아요. 안 급해요.", "practiceQuestion": "I''m sorry for the long wait.", "practiceQuestionTranslation": "오래 기다리게 해서 죄송해요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1965/practice-examples/2b48e618-3c49-472f-8acc-75ac6659d4d6.webp", "sentenceWords": ["That''s", "okay", "No", "hurry"], "sentenceWordChoices": ["okay", "Not", "hurries", "That", "hurry", "That''s", "No"], "sentenceTranslateWords": ["괜찮아요", "안", "급해요"], "sentenceTranslateWordChoices": ["급했어요", "안", "괜찮아요", "안돼요", "급해요", "많이"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1966,21,'CONVERSATION_SKILL','BASIC','EN','KR',4,'by text','문자로','연락 방법을 고르는 by text','''문자로''라는 뜻이에요. 연락 수단 앞에는 by를 붙여요(by text, by email, by phone). 어떻게 연락받을지 물어볼 때 By text, please.라고만 짧게 답해도 충분해요.','Should we call you or send a text?','전화드릴까요, 문자를 보내드릴까요?','By text, please. Thank you.','문자로 부탁드려요. 감사합니다.',ARRAY['By','text','please','Thank','you']::varchar[],ARRAY['please','texts','text','By','Thanks','you','Thank','For']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1966/representative/9ca68359-70e1-403d-b9cb-9b06c733d57d.webp','[{"sentenceText": "By text is best for me.", "highlightingPart": "By text", "sentenceTranslation": "저는 문자가 제일 좋아요.", "practiceQuestion": "How should I contact you?", "practiceQuestionTranslation": "어떻게 연락드릴까요?", "imageUrl": null, "sentenceWords": ["By", "text", "is", "best", "for", "me"], "sentenceWordChoices": ["me", "text", "For", "I", "texts", "By", "best", "for", "is"], "sentenceTranslateWords": ["저는", "문자가", "제일", "좋아요"], "sentenceTranslateWordChoices": ["싫어요", "문자가", "좋았어요", "제일", "좋아요", "전화가", "저는"]}, {"sentenceText": "No, by text, please.", "highlightingPart": "by text", "sentenceTranslation": "아니요, 문자로 부탁드려요.", "practiceQuestion": "Do you want an email?", "practiceQuestionTranslation": "이메일로 드릴까요?", "imageUrl": null, "sentenceWords": ["No", "by", "text", "please"], "sentenceWordChoices": ["for", "Yes", "by", "texts", "No", "text", "please"], "sentenceTranslateWords": ["아니요", "문자로", "부탁드려요"], "sentenceTranslateWordChoices": ["아니요", "전화로", "부탁드려요", "문자로", "부탁드렸어요", "네"]}, {"sentenceText": "Please send it by text.", "highlightingPart": "by text", "sentenceTranslation": "문자로 보내 주세요.", "practiceQuestion": "I''ll send the room number.", "practiceQuestionTranslation": "방 번호를 보내드릴게요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1966/practice-examples/03eeb048-830d-451a-88ea-552c69bd3bf7.webp", "sentenceWords": ["Please", "send", "it", "by", "text"], "sentenceWordChoices": ["send", "Please", "sends", "by", "it", "for", "texts", "text"], "sentenceTranslateWords": ["문자로", "보내", "주세요"], "sentenceTranslateWordChoices": ["보냈어요", "문자로", "주세요", "보내", "가져다", "전화로"]}, {"sentenceText": "They told me by text.", "highlightingPart": "by text", "sentenceTranslation": "문자로 알려 줬어요.", "practiceQuestion": "How did you hear about it?", "practiceQuestionTranslation": "그건 어떻게 아셨어요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1966/practice-examples/0d52a33f-e364-44fd-9683-3dd9cbe2b876.webp", "sentenceWords": ["They", "told", "me", "by", "text"], "sentenceWordChoices": ["me", "told", "They", "for", "text", "by", "tells", "texts"], "sentenceTranslateWords": ["문자로", "알려", "줬어요"], "sentenceTranslateWordChoices": ["알려", "물어봤어요", "전화로", "줬어요", "문자로", "줄게요"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1967,21,'DAILY_ROUTINE','BASIC','EN','KR',1,'I think I left ~ in ~','~을 …에 두고 온 것 같아요','어디에 두고 왔는지 짐작해 말하는 I think I left ~ in ~','''~을 …에 두고 온 것 같아요''라고 확실하지 않은 기억을 말할 때 쓰는 표현이에요. lost는 어디 있는지 전혀 모를 때, left는 둔 자리가 짐작될 때 써요. 앞에 I think를 붙이면 단정하지 않는 느낌이 돼요.','Where did you last see your key?','키를 마지막으로 어디서 보셨어요?','I think I left it in the laundry room.','세탁실에 두고 온 것 같아요.',ARRAY['I','think','I','left','it','in','the','laundry','room']::varchar[],ARRAY['laundry','left','it','I','think','on','in','I','leave','the','them','room']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1967/representative/3d7fa3ff-41d4-4c1d-9fb7-878ef9b8cfca.webp','[{"sentenceText": "I think I left my key in my room.", "highlightingPart": "I think I left", "sentenceTranslation": "키를 방에 두고 온 것 같아요.", "practiceQuestion": "Have you checked your pockets?", "practiceQuestionTranslation": "주머니는 확인해 보셨어요?", "imageUrl": null, "sentenceWords": ["I", "think", "I", "left", "my", "key", "in", "my", "room"], "sentenceWordChoices": ["my", "on", "left", "I", "leave", "I", "think", "keys", "in", "my", "room", "key"], "sentenceTranslateWords": ["키를", "방에", "두고", "온", "것", "같아요"], "sentenceTranslateWordChoices": ["두고", "온", "방에", "잃어버렸어요", "것", "가져왔어요", "교실에", "같아요", "키를"]}, {"sentenceText": "I think I left my bag in the library.", "highlightingPart": "I think I left", "sentenceTranslation": "가방을 도서관에 두고 온 것 같아요.", "practiceQuestion": "Did you take everything with you?", "practiceQuestionTranslation": "물건은 다 챙기셨어요?", "imageUrl": null, "sentenceWords": ["I", "think", "I", "left", "my", "bag", "in", "the", "library"], "sentenceWordChoices": ["think", "I", "library", "on", "left", "I", "bags", "leave", "bag", "in", "my", "the"], "sentenceTranslateWords": ["가방을", "도서관에", "두고", "온", "것", "같아요"], "sentenceTranslateWordChoices": ["온", "샀어요", "식당에", "도서관에", "것", "두고", "가방을", "가져왔어요", "같아요"]}, {"sentenceText": "This morning. I think I left it in the gym.", "highlightingPart": "I think I left", "sentenceTranslation": "오늘 아침에요. 체육관에 두고 온 것 같아요.", "practiceQuestion": "When did you notice it was gone?", "practiceQuestionTranslation": "언제 없어진 걸 아셨어요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1967/practice-examples/979e7c10-a9c0-4f8b-95e3-37d38156dc26.webp", "sentenceWords": ["This", "morning", "I", "think", "I", "left", "it", "in", "the", "gym"], "sentenceWordChoices": ["in", "evening", "I", "This", "gym", "left", "on", "think", "it", "the", "I", "morning", "leave"], "sentenceTranslateWords": ["오늘", "아침에요", "체육관에", "두고", "온", "것", "같아요"], "sentenceTranslateWordChoices": ["것", "체육관에", "가져왔어요", "어젯밤에요", "같아요", "온", "두고", "아침에요", "카페에", "오늘"]}, {"sentenceText": "Yes, please. I think I left it in the cafe.", "highlightingPart": "I think I left", "sentenceTranslation": "네, 부탁드려요. 카페에 두고 온 것 같아요.", "practiceQuestion": "Should I check the lost and found?", "practiceQuestionTranslation": "분실물 센터를 확인해 볼까요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1967/practice-examples/27680737-cec2-4f76-9a46-04a27c106acc.webp", "sentenceWords": ["Yes", "please", "I", "think", "I", "left", "it", "in", "the", "cafe"], "sentenceWordChoices": ["the", "leave", "on", "I", "I", "Yes", "left", "cafes", "in", "cafe", "it", "please", "think"], "sentenceTranslateWords": ["네", "부탁드려요", "카페에", "두고", "온", "것", "같아요"], "sentenceTranslateWordChoices": ["두고", "부탁드려요", "가져왔어요", "아니요", "것", "온", "버스에", "카페에", "네", "같아요"]}]'::jsonb,'SCENARIO','ACTIVE',3,now(),now()),
(1968,21,'CONVERSATION_SKILL','BASIC','EN','KR',2,'What should I do?','어떻게 해야 하나요?','다음에 뭘 해야 할지 묻는 What should I do?','''어떻게 해야 하나요?'', ''제가 뭘 하면 되나요?''라고 다음 행동을 묻는 표현이에요. should는 ''~하는 게 좋다''는 뜻이라 조언을 구하는 느낌이 돼요. 문제 상황에서 상대에게 안내를 부탁할 때 아주 자주 써요.','We can lend you a temporary key or have a staff member open your door.','임시 키를 빌려드리거나 직원이 문을 열어드릴 수 있어요.','What should I do to get a temporary key?','임시 키를 받으려면 어떻게 해야 하나요?',ARRAY['What','should','I','do','to','get','a','temporary','key']::varchar[],ARRAY['to','do','doing','What','should','shall','I','gets','temporary','a','key','get']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1968/representative/685cc1d9-e2b5-4b55-978a-669524a0ca7b.webp','[{"sentenceText": "Okay. What should I do after that?", "highlightingPart": "What should I do", "sentenceTranslation": "알겠어요. 그다음엔 어떻게 해야 하나요?", "practiceQuestion": "You''ll need to fill out a form first.", "practiceQuestionTranslation": "먼저 서류를 작성하셔야 해요.", "imageUrl": null, "sentenceWords": ["Okay", "What", "should", "I", "do", "after", "that"], "sentenceWordChoices": ["shall", "Okay", "do", "I", "What", "should", "doing", "before", "after", "that"], "sentenceTranslateWords": ["알겠어요", "그다음엔", "어떻게", "해야", "하나요"], "sentenceTranslateWordChoices": ["어떻게", "알겠어요", "해야", "그전엔", "했나요", "그다음엔", "어디서", "하나요"]}, {"sentenceText": "What should I do if it happens on a Sunday?", "highlightingPart": "What should I do", "sentenceTranslation": "일요일에 이런 일이 생기면 어떻게 해야 하나요?", "practiceQuestion": "The office is closed on weekends.", "practiceQuestionTranslation": "사무실은 주말에 문을 닫아요.", "imageUrl": null, "sentenceWords": ["What", "should", "I", "do", "if", "it", "happens", "on", "a", "Sunday"], "sentenceWordChoices": ["I", "What", "do", "if", "happen", "a", "should", "Sunday", "shall", "it", "on", "happens", "Monday"], "sentenceTranslateWords": ["일요일에", "이런", "일이", "생기면", "어떻게", "해야", "하나요"], "sentenceTranslateWordChoices": ["일이", "일요일에", "어떻게", "하나요", "월요일에", "해야", "생기면", "누가", "했나요", "이런"]}, {"sentenceText": "What should I do until then?", "highlightingPart": "What should I do", "sentenceTranslation": "그때까지는 어떻게 해야 하나요?", "practiceQuestion": "Your key will be ready in two days.", "practiceQuestionTranslation": "키는 이틀 뒤에 준비돼요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1968/practice-examples/8ca87959-c737-44ea-8d8d-512059f5ce8d.webp", "sentenceWords": ["What", "should", "I", "do", "until", "then"], "sentenceWordChoices": ["shall", "should", "then", "until", "doing", "I", "from", "What", "do"], "sentenceTranslateWords": ["그때까지는", "어떻게", "해야", "하나요"], "sentenceTranslateWordChoices": ["하나요", "어떻게", "그때까지는", "해야", "했나요", "그때부터는", "누구를"]}, {"sentenceText": "I won''t. What should I do when I find my old key?", "highlightingPart": "What should I do", "sentenceTranslation": "네. 원래 키를 찾으면 어떻게 해야 하나요?", "practiceQuestion": "Please don''t lose the temporary key.", "practiceQuestionTranslation": "임시 키는 잃어버리지 않게 조심해 주세요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1968/practice-examples/449041ef-4286-4c60-8dad-153c858eb4f4.webp", "sentenceWords": ["I", "won''t", "What", "should", "I", "do", "when", "I", "find", "my", "old", "key"], "sentenceWordChoices": ["key", "when", "What", "shall", "finds", "I", "find", "old", "do", "should", "I", "my", "won''t", "lose", "I"], "sentenceTranslateWords": ["네", "원래", "키를", "찾으면", "어떻게", "해야", "하나요"], "sentenceTranslateWordChoices": ["잃어버리면", "찾으면", "하나요", "네", "언제", "어떻게", "했나요", "원래", "해야", "키를"]}]'::jsonb,'SCENARIO','ACTIVE',2,now(),now()),
(1969,21,'TIME_PLANNING','BASIC','EN','KR',3,'be ready by ~','~까지 준비되다','언제까지 준비되는지 확인하는 be ready by ~','''~까지 준비된다''는 뜻이에요. by는 ''늦어도 그 시점까지''라는 마감을 나타내서, ''그 시각 내내''라는 뜻의 until과 달라요. 언제 받을 수 있는지 확인할 때 딱 맞는 표현이에요.','A replacement key can be ready tomorrow morning or afternoon.','새 키는 내일 오전이나 오후에 준비돼요.','Will it be ready by noon?','정오까지 준비될까요?',ARRAY['Will','it','be','ready','by','noon']::varchar[],ARRAY['Will','by','ready','until','it','Was','be','noon','readily']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1969/representative/34bf331d-ef74-4eb6-ab00-c9fb840ebac9.webp','[{"sentenceText": "Can it be ready by Friday?", "highlightingPart": "be ready by", "sentenceTranslation": "금요일까지 준비될 수 있을까요?", "practiceQuestion": "When do you need the key?", "practiceQuestionTranslation": "키가 언제 필요하세요?", "imageUrl": null, "sentenceWords": ["Can", "it", "be", "ready", "by", "Friday"], "sentenceWordChoices": ["until", "by", "it", "be", "ready", "Monday", "Can", "Friday", "readily"], "sentenceTranslateWords": ["금요일까지", "준비될", "수", "있을까요"], "sentenceTranslateWordChoices": ["금요일까지", "수", "있을까요", "어디서", "월요일까지", "준비됐어요", "준비될"]}, {"sentenceText": "Then it should be ready by two.", "highlightingPart": "be ready by", "sentenceTranslation": "그럼 두 시까지 준비돼야 해요.", "practiceQuestion": "I have a class at three.", "practiceQuestionTranslation": "저는 세 시에 수업이 있어요.", "imageUrl": null, "sentenceWords": ["Then", "it", "should", "be", "ready", "by", "two"], "sentenceWordChoices": ["two", "ready", "four", "readily", "it", "Then", "be", "by", "until", "should"], "sentenceTranslateWords": ["그럼", "두", "시까지", "준비돼야", "해요"], "sentenceTranslateWordChoices": ["준비돼야", "그럼", "다섯", "준비됐어요", "시까지", "네", "해요", "두"]}, {"sentenceText": "Will everything be ready by then?", "highlightingPart": "be ready by", "sentenceTranslation": "그때까지 다 준비될까요?", "practiceQuestion": "The workers start at nine.", "practiceQuestionTranslation": "작업자들은 아홉 시에 시작해요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1969/practice-examples/3dc3f285-7eba-4b0e-9899-650ad7864a4b.webp", "sentenceWords": ["Will", "everything", "be", "ready", "by", "then"], "sentenceWordChoices": ["ready", "until", "Will", "by", "Was", "be", "readily", "everything", "then"], "sentenceTranslateWords": ["그때까지", "다", "준비될까요"], "sentenceTranslateWordChoices": ["그때부터", "조금", "준비될까요", "준비됐어요", "다", "그때까지"]}, {"sentenceText": "I hope they''ll be ready by tomorrow.", "highlightingPart": "be ready by", "sentenceTranslation": "내일까지 준비되면 좋겠어요.", "practiceQuestion": "Your documents are still being checked.", "practiceQuestionTranslation": "서류는 아직 확인 중이에요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1969/practice-examples/424be483-3261-45f2-a75d-813510102d50.webp", "sentenceWords": ["I", "hope", "they''ll", "be", "ready", "by", "tomorrow"], "sentenceWordChoices": ["readily", "hope", "tomorrow", "they''ll", "by", "be", "I", "today", "until", "ready"], "sentenceTranslateWords": ["내일까지", "준비되면", "좋겠어요"], "sentenceTranslateWordChoices": ["준비됐어요", "싫어요", "준비되면", "내일까지", "좋겠어요", "오늘까지"]}]'::jsonb,'SCENARIO','ACTIVE',3,now(),now()),
(1970,21,'TIME_PLANNING','BASIC','EN','KR',4,'as soon as possible','가능한 한 빨리','최대한 빨리 부탁하는 as soon as possible','''가능한 한 빨리''라는 뜻이에요. 직역하면 ''가능한 만큼 빨리''인데, 상대를 재촉하지 않으면서 급하다는 걸 전할 수 있어요. 줄여서 ASAP라고도 쓰지만 말할 땐 풀어서 쓰는 게 더 정중해요.','Would you like a text or a phone call when it''s ready?','준비되면 문자와 전화 중 어떤 방법으로 알려드릴까요?','A text, please. And as soon as possible.','문자로 부탁드려요. 그리고 가능한 한 빨리요.',ARRAY['A','text','please','And','as','soon','as','possible']::varchar[],ARRAY['soon','as','soonest','A','please','possibly','And','Or','text','possible','as']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1970/representative/b98a21a4-00dc-413b-85be-0120ec1f881d.webp','[{"sentenceText": "As soon as possible, please.", "highlightingPart": "As soon as possible", "sentenceTranslation": "가능한 한 빨리 부탁드려요.", "practiceQuestion": "When do you need an answer?", "practiceQuestionTranslation": "언제까지 답이 필요하세요?", "imageUrl": null, "sentenceWords": ["As", "soon", "as", "possible", "please"], "sentenceWordChoices": ["soonest", "please", "soon", "possible", "Was", "possibly", "as", "As"], "sentenceTranslateWords": ["가능한", "한", "빨리", "부탁드려요"], "sentenceTranslateWordChoices": ["빨리", "나중에", "한", "천천히", "부탁드려요", "가능한", "부탁드렸어요"]}, {"sentenceText": "Thank you. Please tell them as soon as possible.", "highlightingPart": "as soon as possible", "sentenceTranslation": "감사합니다. 가능한 한 빨리 전해 주세요.", "practiceQuestion": "I''ll call the maintenance team.", "practiceQuestionTranslation": "시설팀에 연락할게요.", "imageUrl": null, "sentenceWords": ["Thank", "you", "Please", "tell", "them", "as", "soon", "as", "possible"], "sentenceWordChoices": ["you", "soonest", "possibly", "as", "as", "tell", "soon", "them", "possible", "Please", "Thank", "him"], "sentenceTranslateWords": ["감사합니다", "가능한", "한", "빨리", "전해", "주세요"], "sentenceTranslateWordChoices": ["가능한", "주세요", "전했어요", "천천히", "빨리", "죄송합니다", "한", "전해", "감사합니다"]}, {"sentenceText": "Yes, I need it as soon as possible.", "highlightingPart": "as soon as possible", "sentenceTranslation": "네, 가능한 한 빨리 필요해요.", "practiceQuestion": "Is this urgent?", "practiceQuestionTranslation": "급하신가요?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1970/practice-examples/aeda2315-4371-41c3-ab2b-6950dda99b42.webp", "sentenceWords": ["Yes", "I", "need", "it", "as", "soon", "as", "possible"], "sentenceWordChoices": ["needs", "soonest", "I", "it", "soon", "need", "Yes", "possible", "as", "as", "possibly"], "sentenceTranslateWords": ["네", "가능한", "한", "빨리", "필요해요"], "sentenceTranslateWordChoices": ["빨리", "가능한", "아니요", "필요해요", "천천히", "한", "네", "필요했어요"]}, {"sentenceText": "Could you do it as soon as possible?", "highlightingPart": "as soon as possible", "sentenceTranslation": "가능한 한 빨리 해 주실 수 있을까요?", "practiceQuestion": "We''ll process it this week.", "practiceQuestionTranslation": "이번 주 안에 처리해 드릴게요.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/21/expressions/1970/practice-examples/3bc5121f-3cdf-49c4-a273-399e0b35d249.webp", "sentenceWords": ["Could", "you", "do", "it", "as", "soon", "as", "possible"], "sentenceWordChoices": ["possible", "do", "as", "does", "it", "you", "possibly", "as", "soon", "Could", "soonest"], "sentenceTranslateWords": ["가능한", "한", "빨리", "해", "주실", "수", "있을까요"], "sentenceTranslateWordChoices": ["한", "수", "빨리", "있을까요", "어디서", "가능한", "해", "했어요", "천천히", "주실"]}]'::jsonb,'SCENARIO','ACTIVE',3,now(),now()),
(1971,23,'CONVERSATION_SKILL','BASIC','EN','KR',1,'I found it','찾았어','찾았다고 알리는 I found it','찾던 물건을 발견했을 때 ''찾았어''라고 알리는 표현이에요. find의 과거형 found를 써요. 뒤에 물건 이름을 넣어 I found your shirt처럼 무엇을 찾았는지 밝힐 수도 있어요.','I have your white shirt. Do you see my blue shirt?','네 흰 셔츠가 나한테 있어. 내 파란 셔츠 보여?','Yes, I found it here.','응, 여기서 찾았어.',ARRAY['Yes','I','found','it','here']::varchar[],ARRAY['found','it','there','Yes','I','find','them','here']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1971/representative/a0c3db80-531f-464f-ad2d-68c0aea85aad.webp','[{"sentenceText": "I found it. Here you go.", "highlightingPart": "I found it", "sentenceTranslation": "찾았어. 여기.", "practiceQuestion": "Is my sock in your basket?", "practiceQuestionTranslation": "내 양말 네 바구니에 있어?", "imageUrl": null, "sentenceWords": ["I", "found", "it", "Here", "you", "go"], "sentenceWordChoices": ["find", "it", "them", "found", "I", "you", "Here", "go", "goes"], "sentenceTranslateWords": ["찾았어", "여기"], "sentenceTranslateWordChoices": ["찾을게", "못찾겠어", "여기", "찾았어", "저기"]}, {"sentenceText": "I found it under the machine.", "highlightingPart": "I found it", "sentenceTranslation": "세탁기 밑에서 찾았어.", "practiceQuestion": "Did you see my blue towel?", "practiceQuestionTranslation": "내 파란 수건 봤어?", "imageUrl": null, "sentenceWords": ["I", "found", "it", "under", "the", "machine"], "sentenceWordChoices": ["I", "under", "them", "find", "over", "machine", "found", "the", "it"], "sentenceTranslateWords": ["세탁기", "밑에서", "찾았어"], "sentenceTranslateWordChoices": ["찾았어", "밑에서", "못찾겠어", "세탁기", "찾을게", "위에서"]}, {"sentenceText": "I found it already. Thanks!", "highlightingPart": "I found it", "sentenceTranslation": "벌써 찾았어. 고마워!", "practiceQuestion": "Your bag was not in the room.", "practiceQuestionTranslation": "네 가방 방에 없던데.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/23/expressions/1971/practice-examples/da2dc5a2-4139-4f51-9a60-7127d6d0e032.webp", "sentenceWords": ["I", "found", "it", "already", "Thanks"], "sentenceWordChoices": ["find", "Thank", "Thanks", "them", "found", "already", "I", "it"], "sentenceTranslateWords": ["벌써", "찾았어", "고마워"], "sentenceTranslateWordChoices": ["벌써", "찾았어", "못찾겠어", "미안해", "아직", "고마워"]}, {"sentenceText": "I found it in my pile.", "highlightingPart": "I found it", "sentenceTranslation": "내 빨래 더미에서 찾았어.", "practiceQuestion": "Where was my white T-shirt?", "practiceQuestionTranslation": "내 흰 티셔츠 어디 있었어?", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/23/expressions/1971/practice-examples/afc81fdd-044b-4bd9-933c-178bcf4c7304.webp", "sentenceWords": ["I", "found", "it", "in", "my", "pile"], "sentenceWordChoices": ["piles", "find", "pile", "in", "I", "them", "it", "my", "found"], "sentenceTranslateWords": ["내", "빨래", "더미에서", "찾았어"], "sentenceTranslateWordChoices": ["찾을게", "빨래", "못찾겠어", "내", "찾았어", "더미에서", "네"]}]'::jsonb,'SCENARIO','ACTIVE',1,now(),now()),
(1972,23,'CONVERSATION_SKILL','BASIC','EN','KR',2,'Here it is','여기 있어','물건을 건네줄 때 쓰는 Here it is','물건을 건네주면서 ''여기 있어''라고 말하는 표현이에요. 여러 개를 건넬 땐 Here they are로 바꿔요. 상대에게 무언가를 주는 상황이라면 어디서든 그대로 쓸 수 있어요.','Did you find my blue shirt?','내 파란 셔츠 찾았어?','Yes. Here it is.','응. 여기 있어.',ARRAY['Yes','Here','it','is']::varchar[],ARRAY['is','Yes','it','them','There','was','Here']::varchar[],'https://d19azau1un4t7r.cloudfront.net/content/writing-expressions/1972/representative/01714d8a-e952-45d5-b762-831b096e0713.webp','[{"sentenceText": "Of course. Here it is.", "highlightingPart": "Here it is", "sentenceTranslation": "당연하지. 여기 있어.", "practiceQuestion": "Can I get my towel back?", "practiceQuestionTranslation": "내 수건 돌려받을 수 있어?", "imageUrl": null, "sentenceWords": ["Of", "course", "Here", "it", "is"], "sentenceWordChoices": ["it", "Here", "There", "Of", "course", "them", "is", "was"], "sentenceTranslateWords": ["당연하지", "여기", "있어"], "sentenceTranslateWordChoices": ["안돼", "여기", "당연하지", "있었어", "있어", "저기"]}, {"sentenceText": "Here it is, next to the machine.", "highlightingPart": "Here it is", "sentenceTranslation": "여기 있어, 세탁기 옆에.", "practiceQuestion": "Where''s the detergent?", "practiceQuestionTranslation": "세제 어디 있어?", "imageUrl": null, "sentenceWords": ["Here", "it", "is", "next", "to", "the", "machine"], "sentenceWordChoices": ["machines", "next", "Here", "is", "to", "it", "the", "There", "was", "machine"], "sentenceTranslateWords": ["여기", "있어", "세탁기", "옆에"], "sentenceTranslateWordChoices": ["세탁기", "여기", "있어", "옆에", "있었어", "안에", "저기"]}, {"sentenceText": "Here it is. Don''t lose it!", "highlightingPart": "Here it is", "sentenceTranslation": "여기 있어. 잃어버리지 마!", "practiceQuestion": "I need my student card.", "practiceQuestionTranslation": "나 학생증 필요해.", "imageUrl": "https://d19azau1un4t7r.cloudfront.net/content/scenarios/23/expressions/1972/practice-examples/502f1cef-4e6e-43b5-ba97-44d2800b1969.webp", "sentenceWords": ["Here", "it", "is", "Don''t", "lose", "it"], "sentenceWordChoices